# PTX source for fp16 ReLU kernel (sm_80)
PTX_SOURCE = r"""
.version 7.0
.target sm_80
.address_size 64

.visible .entry relu_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u64 N
)
{
    .reg .pred   %p;
    .reg .u64    %tid, %tmp, %input, %output, %in_addr, %out_addr;
    .reg .u32    %tid_x, %block_x, %blockDim_x;
    .reg .f16    %val, %zero;

    // tid = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %tid_x, %tid.x;
    mov.u32 %block_x, %ctaid.x;
    mov.u32 %blockDim_x, %ntid.x;
    mul.wide.u32 %tid, %block_x, %blockDim_x;
    cvt.u64.u32 %tmp, %tid_x;
    add.u64 %tid, %tid, %tmp;

    // load total element count N
    ld.param.u64 %tmp, [N];
    setp.ge.u64 %p, %tid, %tmp;
    @%p bra DONE;

    // load input and output base pointers
    ld.param.u64 %input,  [input_ptr];
    ld.param.u64 %output, [output_ptr];

    // byte offset = tid * sizeof(half) (2 bytes)
    mul.wide.u32 %tmp, %tid, 2;
    add.u64 %in_addr,  %input,  %tmp;
    add.u64 %out_addr, %output, %tmp;

    // load half value
    ld.global.nc.f16 %val, [%in_addr];

    // ReLU: max(val, 0)
    mov.f16 %zero, 0f0000;
    max.f16 %val, %val, %zero;

    // store result
    st.global.nc.f16 [%out_addr], %val;

DONE:
    ret;
}
"""

import torch
import torch.nn as nn
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16
        out = torch.empty_like(x)
        N = x.numel()
        block = 256
        grid = (N + block - 1) // block
        # launch PTX kernel
        ptx_launch(
            self.module,
            "relu_kernel",
            grid,
            block,
            [x.data_ptr(), out.data_ptr(), N]
        )
        return out
